style.css:
@-moz-document domain("google.com") {
/* 1. FONDO DE GOOGLE: Rosa Pastel con Círculos Blancos */
    body, #gsr, #main, #cnt, .main, [role="main"], #searchform, 
    #center_col, .content, .mw, #rcnt, .GyAeWb, .main-content {
        background-color: #FFDEE9 !important; /* Rosa pastel base */
        background-image: radial-gradient(#FFFFFF 20%, transparent 20%),
                          radial-gradient(#FFFFFF 20%, transparent 20%) !important;
        background-size: 30px 30px !important; /* Tamaño de los círculos */
        background-position: 0 0, 15px 15px !important; /* Alineación perfecta */
    }

    /* Borramos las capas blancas de Google para que se vean los círculos */
    .sfbg, .fbar, #footcnt, .appbar, .yg51cc, .E2v3ic, .rhscenter, #rhs {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 2. TEXTOS: Blanco legible con delineado oscuro */
    h3, span, p, a, em, div, cite, .VwiC3b, .LC20lb, a h3 {
        color: #FFFFFF !important;
        text-shadow: -1px -1px 0 #4A4A4A, 1px -1px 0 #4A4A4A, -1px 1px 0 #4A4A4A, 1px 1px 0 #4A4A4A !important;
    }
    a:link, a:visited {
        color: #FFFFFF !important;
    }

    /* 3. ICONOS GENERALES: Blanco Puro */
    svg, path, [role="button"] svg {
        fill: #FFFFFF !important;
        color: #FFFFFF !important;
    }

    /* 4. EL BUSCADOR CENTRAL: Amarillo Pollito Limpio */
    .RNNXgb {
        background-color: #FFF59D !important;
        border: 2px dashed #FFB7CE !important; /* Líneas rosadas del buscador */
        border-radius: 28px !important;
        box-shadow: 2px 2px 8px rgba(0,0,0,0.1) !important;
    }
    input[type="text"], .gLFyf, .X0YpS, .G0iuY {
        color: #4A4A4A !important;
        fill: #4A4A4A !important;
    }

    /* 5. MARCOS ROSADOS ALREDEDOR DE LOS RESULTADOS (Sin duplicados) */
    .g .jGvY9, .MjjYud > .g, .Ww4FFb {
        border: 3px dashed #FFB7CE !important; /* Líneas discontinuas ordenadas */
        border-radius: 16px !important;
        padding: 16px !important;
        background-color: rgba(255, 240, 245, 0.7) !important; /* Capa rosa suave sobre los círculos */
        margin-bottom: 20px !important;
        box-shadow: 3px 3px 10px rgba(0,0,0,0.05) !important;
    }

    /* Apagamos líneas locas repetidas */
    div, section, article {
        border-color: transparent;
    }
}
